async function viewTenants(e){const n=await api("/properties"),a=await Promise.all(n.map(e=>api(`/properties/${e.id}/tenant`).catch(()=>({tenants:[],invite_code:null})))),t=n.map((e,n)=>({p:e,info:a[n]||{tenants:[]}})).filter(({p:e,info:n})=>n.tenants&&n.tenants.length||n.invite_code||e.rent_amount);e.innerHTML='<div class="pagehead"><div><h1>Tenants</h1>\n    <p>Codes, rent, invoices, meter readings and maintenance for your rented properties — in one place.</p></div></div>\n    '+(t.length?'<div id="tenlist"></div>':'<div class="card empty"><b>No rented properties yet</b>Set a rent amount or generate a tenant code on a property, and it shows up here.</div>');const s=$("#tenlist");for(const{p:e,info:n}of t){const a=(n.tenants||[]).map(e=>e.name).join(", "),r=a?esc(a):n.invite_code?tr("code ready — no tenant yet"):tr("no tenant yet"),i=document.createElement("details");i.className="entity",i.open=1===t.length,i.innerHTML=`<summary>\n      <span><b>${esc(e.name)}</b>${e.managed?` <span class="badge role">${tr("managed")}</span>`:""}${e.address?` <span class="muted">${esc(e.address)}</span>`:""}</span>\n      <span class="row"><span class="muted">${r}</span>\n        <a class="btn small" data-nav href="#property/${e.id}">${tr("Dashboard")} →</a></span></summary><div class="body"></div>`,i.querySelector("[data-nav]").addEventListener("click",e=>e.stopPropagation()),s.appendChild(i),renderTenantBox(i.querySelector(".body"),e)}}